// Generated by vuetify-ext bootstrap app
import { EnvironmentTag, StatusBadge, type AppMain, type AppShellContent } from 'vuetify-extended';

export function buildFooterStart(_app: AppMain): AppShellContent[] {
  return [
    new StatusBadge({
      text: { key: "bootstrap.footer.start", fallback: "vuetify-extended Starter" },
      icon: 'mdi-flask-outline',
      color: 'primary',
      variant: 'outlined',
    }),
  ];
}

export function buildFooterCenter(_app: AppMain): AppShellContent[] {
  return [
    new EnvironmentTag({
      text: { key: "bootstrap.footer.center", fallback: "Bootstrap + Pages + Menu" },
      color: 'secondary',
      variant: 'outlined',
    }),
  ];
}

export function buildFooterEnd(_app: AppMain): AppShellContent[] {
  return [
    new StatusBadge({
      text: { key: "bootstrap.footer.end", fallback: "Home Page Ready" },
      icon: 'mdi-home-outline',
      color: 'success',
      variant: 'tonal',
    }),
  ];
}
